-- Local/demo data only (db/local). Adds many more fictional hotels across all 25 Cambodian provinces so that
-- browsing, search paging and province filters have realistic volume. Hotel names are invented; the streets,
-- neighbourhoods and landmarks mentioned are real places in each province. Generated with a fixed seed.




-- Policy by price level: budget stays are the most flexible, upscale stays the strictest.
SELECT h.id,
       CASE WHEN p.min_price<30 THEN 'Flexible' WHEN p.min_price<80 THEN 'Flexible' ELSE 'Moderate' END,
       CASE WHEN p.min_price<30 THEN 24 WHEN p.min_price<80 THEN 48 ELSE 72 END,
       CASE WHEN p.min_price<30 THEN 100 WHEN p.min_price<80 THEN 50 ELSE 25 END, true
FROM hotel h JOIN (SELECT hotel_id,min(base_price) AS min_price FROM room_type GROUP BY hotel_id) p ON p.hotel_id=h.id WHERE h.id>='10000000-0000-4000-8000-000000000026' AND h.id<'10000000-0000-4000-8001-000000000000';

-- Same seasonal pattern as V901/V902: dry high season and Khmer New Year.
SELECT id,DATE '2026-12-01',DATE '2027-02-01',round(base_price*1.20,0),currency,1 FROM room_type WHERE hotel_id>='10000000-0000-4000-8000-000000000026' AND hotel_id<'10000000-0000-4000-8001-000000000000'
UNION ALL
SELECT id,DATE '2027-04-13',DATE '2027-04-17',round(base_price*1.35,0),currency,10 FROM room_type WHERE hotel_id>='10000000-0000-4000-8000-000000000026' AND hotel_id<'10000000-0000-4000-8001-000000000000';
